import re

def parse(lines):
    settings = {}
    ctl = {}
    flags = []
    sl = []
    cl = []
    fl = []
    for i, l in enumerate(lines):
        s = l.strip()
        if not s:
            continue
        if ';' in s:
            is_settings = bool(re.match(r'^(speed|rows|columns|line)\b', s))
            target = settings if is_settings else ctl
            for part in s.split(';'):
                p = part.strip()
                if not p:
                    continue
                m = re.match(r'^(\S+)\s*=\s*(.*)$', p)
                if not m:
                    m = re.match(r'^(\S+)\s+(.*)$', p)
                if m:
                    k = m.group(1)
                    v = m.group(2).strip()
                    if k in ('speed', 'rows', 'columns', 'line'):
                        settings[k] = v
                    else:
                        target[k] = v
            if is_settings:
                sl.append(i)
            else:
                cl.append(i)
        else:
            ok = False
            for tok in s.split():
                if re.match(r'^-?[A-Za-z][A-Za-z0-9]*$', tok):
                    ok = True
                    if tok.startswith('-'):
                        flags.append({'flag': tok[1:], 'enabled': 'no'})
                    else:
                        flags.append({'flag': tok, 'enabled': 'yes'})
            if ok:
                fl.append(i)
    blocks = []
    if settings:
        blocks.append({'name': 'settings', 'kind': 'kv', 'lines': sl, 'records': [settings]})
    if ctl:
        blocks.append({'name': 'control_characters', 'kind': 'kv', 'lines': cl, 'records': [ctl]})
    if flags:
        blocks.append({'name': 'flags', 'kind': 'table', 'lines': fl, 'records': flags})
    return {'blocks': blocks, 'skip': []}

